#include "thesis_jaco_perception/multipose_association.hpp"
#include <algorithm>
#include <cmath>
namespace thesis_jaco_perception { namespace { Point3 tx(const Point3&p,const std::array<double,6>&x){const double a=x[3],b=x[4],c=x[5],cx=cos(a),sx=sin(a),cy=cos(b),sy=sin(b),cz=cos(c),sz=sin(c);return{x[0]+cz*cy*p.x+(cz*sy*sx-sz*cx)*p.y+(cz*sy*cx+sz*sx)*p.z,x[1]+sz*cy*p.x+(sz*sy*sx+cz*cx)*p.y+(sz*sy*cx-cz*sx)*p.z,x[2]-sy*p.x+cy*sx*p.y+cy*cx*p.z};} }
std::vector<MultiPoseCorrespondence> associate_multipose(const std::vector<std::vector<Point3>>&clouds,const std::vector<std::vector<Capsule3>>&capsules,const std::array<double,6>&pose,const AssociationRound&r,std::size_t round){std::vector<MultiPoseCorrespondence>o;if(clouds.size()!=capsules.size())return o;for(std::size_t i=0;i<clouds.size();++i)for(std::size_t j=0;j<clouds[i].size();++j){auto w=tx(clouds[i][j],pose);double a=1e9,b=1e9;std::size_t k=0;for(std::size_t q=0;q<capsules[i].size();++q){double d=std::abs(point_segment_distance(w,capsules[i][q].start,capsules[i][q].end)-capsules[i][q].radius);if(d<a){b=a;a=d;k=q;}else if(d<b)b=d;}if(a<=r.gate&&b-a>=r.margin)o.push_back({i,j,k,round,clouds[i][j],a,b});}return o;}}
